from __future__ import annotations

import json
from pathlib import Path


def cell(kind: str, source: str) -> dict:
    return {"cell_type": kind, "metadata": {}, "source": source.splitlines(True), **({"outputs": [], "execution_count": None} if kind == "code" else {})}


cells = [
    cell("markdown", "# Fine-tune PhoBERT 5 lớp cảm xúc tiếng Việt\n\nNotebook này bám theo `PhoBERT_5Class_Vietnamese_Sentiment_Pipeline.md`: chỉ dùng `text` làm input; `label` 1–5 là target. Không đưa `rating_raw`, star, ID hay metadata vào model. Train tối đa 50 epoch, chọn best checkpoint theo validation macro-F1 và early stopping.\n"),
    cell("code", """from pathlib import Path\nimport json, random, re, unicodedata\nimport numpy as np\nimport pandas as pd\nimport torch\nfrom sklearn.metrics import accuracy_score, classification_report, f1_score, cohen_kappa_score, mean_absolute_error\nfrom transformers import (AutoTokenizer, AutoModelForSequenceClassification, DataCollatorWithPadding,\n                          EarlyStoppingCallback, Trainer, TrainingArguments)\n\nROOT = Path.cwd()\nif not (ROOT / 'data').exists():\n    ROOT = Path('..').resolve()\nDATA_DIR = ROOT / 'data' / 'phanloaicamxuc'\nARTIFACT_DIR = ROOT / 'selector' / 'artifacts' / 'phobert_5class'\nMODEL_NAME = 'vinai/phobert-base-v2'\nMAX_LENGTH = 160\nEPOCHS = 50\nEARLY_STOPPING_PATIENCE = 3\nLEARNING_RATE = 2e-5\nBATCH_SIZE = 16\nSEED = 42\n\nrandom.seed(SEED); np.random.seed(SEED); torch.manual_seed(SEED)\nprint(DATA_DIR, ARTIFACT_DIR)\n"""),
    cell("code", """def normalize_text(value):\n    text = unicodedata.normalize('NFC', str(value)).strip()\n    text = re.sub(r'\\s+', ' ', text)\n    return text\n\ndef load_split(name):\n    frame = pd.read_csv(DATA_DIR / f'{name}.csv')\n    required = {'text', 'label'}\n    if not required.issubset(frame.columns):\n        raise ValueError(f'{name}.csv must contain text,label')\n    frame = frame[['text', 'label']].dropna().copy()\n    frame['text'] = frame['text'].map(normalize_text)\n    frame['label'] = pd.to_numeric(frame['label'], errors='raise').astype(int)\n    frame = frame[frame['text'].ne('') & frame['label'].between(1, 5)].reset_index(drop=True)\n    return frame\n\ntrain_df = load_split('train')\nval_df = load_split('val')\nprint('train:', train_df.shape, train_df['label'].value_counts().sort_index().to_dict())\nprint('val:', val_df.shape, val_df['label'].value_counts().sort_index().to_dict())\n"""),
    cell("code", """tokenizer = AutoTokenizer.from_pretrained(MODEL_NAME, use_fast=False)\n\nclass SentimentDataset(torch.utils.data.Dataset):\n    def __init__(self, frame):\n        self.encodings = tokenizer(frame['text'].tolist(), truncation=True, max_length=MAX_LENGTH)\n        self.labels = (frame['label'].to_numpy() - 1).tolist()\n    def __len__(self): return len(self.labels)\n    def __getitem__(self, index):\n        item = {key: torch.tensor(value[index]) for key, value in self.encodings.items()}\n        item['labels'] = torch.tensor(self.labels[index], dtype=torch.long)\n        return item\n\ntrain_dataset = SentimentDataset(train_df)\nval_dataset = SentimentDataset(val_df)\nmodel = AutoModelForSequenceClassification.from_pretrained(\n    MODEL_NAME, num_labels=5,\n    id2label={i: f'LABEL_{i+1}' for i in range(5)},\n    label2id={f'LABEL_{i+1}': i for i in range(5)},\n)\n"""),
    cell("code", """def compute_metrics(eval_prediction):\n    logits, labels = eval_prediction\n    predicted = np.argmax(logits, axis=-1) + 1\n    actual = labels + 1\n    return {\n        'accuracy': float(accuracy_score(actual, predicted)),\n        'macro_f1': float(f1_score(actual, predicted, average='macro', zero_division=0)),\n        'mae': float(mean_absolute_error(actual, predicted)),\n        'qwk': float(cohen_kappa_score(actual, predicted, weights='quadratic')),\n    }\n\nargs = TrainingArguments(\n    output_dir=str(ARTIFACT_DIR / 'checkpoints'),\n    learning_rate=LEARNING_RATE, num_train_epochs=EPOCHS,\n    per_device_train_batch_size=BATCH_SIZE, per_device_eval_batch_size=BATCH_SIZE,\n    weight_decay=0.01, eval_strategy='epoch', save_strategy='epoch',\n    load_best_model_at_end=True, metric_for_best_model='macro_f1', greater_is_better=True,\n    save_total_limit=2, fp16=torch.cuda.is_available(), logging_steps=50, report_to='none', seed=SEED,\n)\ntrainer = Trainer(\n    model=model, args=args, train_dataset=train_dataset, eval_dataset=val_dataset,\n    tokenizer=tokenizer, data_collator=DataCollatorWithPadding(tokenizer),\n    compute_metrics=compute_metrics,\n    callbacks=[EarlyStoppingCallback(early_stopping_patience=EARLY_STOPPING_PATIENCE)],\n)\ntrainer.train()\n"""),
    cell("code", """ARTIFACT_DIR.mkdir(parents=True, exist_ok=True)\nmetrics = trainer.evaluate(val_dataset)\ntrainer.save_model(ARTIFACT_DIR)\ntokenizer.save_pretrained(ARTIFACT_DIR)\n(ARTIFACT_DIR / 'training_config.json').write_text(json.dumps({\n    'model_name': MODEL_NAME, 'max_length': MAX_LENGTH, 'epochs': EPOCHS,\n    'early_stopping_patience': EARLY_STOPPING_PATIENCE, 'seed': SEED,\n    'labels': [1, 2, 3, 4, 5], 'validation_metrics': metrics,\n}, ensure_ascii=False, indent=2), encoding='utf-8')\nprint(json.dumps(metrics, ensure_ascii=False, indent=2))\n"""),
    cell("code", """def classify_comment(comment):\n    inputs = tokenizer([normalize_text(comment)], return_tensors='pt', truncation=True, max_length=MAX_LENGTH)\n    device = next(trainer.model.parameters()).device\n    inputs = {key: value.to(device) for key, value in inputs.items()}\n    with torch.no_grad():\n        probabilities = torch.softmax(trainer.model(**inputs).logits, dim=-1)[0].cpu().numpy()\n    label = int(np.argmax(probabilities) + 1)\n    return {'score': label, 'probabilities': probabilities.round(4).tolist(), 'confidence': float(probabilities.max())}\n\nfor comment in ['Ứng dụng chạy rất nhanh và ổn định', 'Tải model quá lâu, máy bị giật lag']:\n    print(comment, '=>', classify_comment(comment))\n"""),
]

notebook = {"cells": cells, "metadata": {"kernelspec": {"display_name": "Python 3", "language": "python", "name": "python3"}, "language_info": {"name": "python", "version": "3.12"}}, "nbformat": 4, "nbformat_minor": 5}
Path('notebooks/train_phobert.ipynb').write_text(json.dumps(notebook, ensure_ascii=False, indent=1), encoding='utf-8')
